            "contentHtml": "<p>Prawo jazdy w Polsce może uzyskać każdy obywatel, który spełnił następujące warunki:</p>\n<ul>\n<li> osiągnięcie wymaganego wieku dla danej kategorii,</li>\n<li> uzyskanie wymaganego orzeczenia lekarskiego o braku przeciwwskazań zdrowotnych do kierowania pojazdem,</li>\n<li> posiadanie zgody rodzica lub opiekuna, jeżeli dana osoba nie ukończyła 18 roku życia,</li>\n<li>odbycie wymaganego szkolenia/ kursu oraz uzyskanie pozytywnego wyniku na egzaminie wewnętrznym,</li>\n<li> zdanie egzaminu państwowego z wynikiem pozytywnym.</li>\n</ul>"
